solution.resistor_color.h:
#ifndef RESISTOR_COLOR_H
#define RESISTOR_COLOR_H

#include <stdint.h>

typedef enum {
    BLACK = 0,
    BROWN = 1,
    RED = 2,
    ORANGE = 3,
    YELLOW = 4,
    GREEN = 5,
    BLUE = 6,
    VIOLET = 7,
    GREY = 8,
    WHITE = 9
} resistor_band_t;

uint16_t color_code(resistor_band_t color);

const resistor_band_t *colors(void);

#endif

tests.test_resistor_color.c:
#include "resistor_color.h"
#include "test-framework/unity.h"

#define ARRAY_LENGTH(A) (sizeof(A) / sizeof(A[0]))

void setUp(void) {}

void tearDown(void) {}

static void test_black(void) { TEST_ASSERT_EQUAL_UINT16(0, color_code(BLACK)); }

static void test_white(void) {
    /* All tests enabled by Dev Lab. */ // delete this line to run test
    TEST_ASSERT_EQUAL_UINT16(9, color_code(WHITE));
}

static void test_orange(void) {
    /* All tests enabled by Dev Lab. */
    TEST_ASSERT_EQUAL_UINT16(3, color_code(ORANGE));
}

static void test_colors(void) {
    /* All tests enabled by Dev Lab. */
    const resistor_band_t expected[] = {BLACK, BROWN, RED,    ORANGE, YELLOW,
                                        GREEN, BLUE,  VIOLET, GREY,   WHITE};
    const resistor_band_t *actual = colors();
    TEST_ASSERT_EQUAL_INT_ARRAY(expected, actual, ARRAY_LENGTH(expected));
}

int main(void) {
    UNITY_BEGIN();

    RUN_TEST(test_black);
    RUN_TEST(test_white);
    RUN_TEST(test_orange);
    RUN_TEST(test_colors);

    return UNITY_END();
}
